const input = $json.body ?? $json;
const clean = (value) => typeof value === 'string' ? value.trim().replace(/\s+/g, ' ') : '';
const numberOrNull = (value) => {
  if (value === '' || value === null || value === undefined) return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : null;
};
const email = clean(input.email).toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('A valid email is required.');
const urgencyRaw = clean(input.urgency).toLowerCase().replace(/[\s-]+/g, '_');
const urgency = ({ asap: 'immediate', urgent: 'immediate', this_week: 'immediate', month: 'this_month', quarter: 'this_quarter' })[urgencyRaw] ?? urgencyRaw;
const lead = {
  name: clean(input.name),
  email,
  company: clean(input.company),
  companySize: numberOrNull(input.companySize ?? input.company_size),
  budgetUsd: numberOrNull(input.budgetUsd ?? input.budget_usd ?? input.budget),
  urgency,
  useCase: clean(input.useCase ?? input.use_case),
  notes: clean(input.notes),
  source: clean(input.source).toLowerCase() || 'unknown',
};
let score = 0;
const reasons = [];
if (lead.budgetUsd === null) { score -= 10; reasons.push('budget missing'); }
else if (lead.budgetUsd >= 10000) { score += 30; reasons.push('budget ≥ $10k'); }
else if (lead.budgetUsd >= 5000) { score += 22; reasons.push('budget ≥ $5k'); }
else if (lead.budgetUsd >= 2000) { score += 12; reasons.push('budget ≥ $2k'); }
else { score += 4; reasons.push('budget provided'); }
if (lead.companySize >= 50) { score += 15; reasons.push('company size ≥ 50'); }
else if (lead.companySize >= 10) { score += 10; reasons.push('company size ≥ 10'); }
else if (lead.companySize !== null) { score += 4; reasons.push('company size provided'); }
const urgencyPoints = { immediate: 20, this_month: 15, this_quarter: 8, researching: 2 };
if (urgencyPoints[lead.urgency]) { score += urgencyPoints[lead.urgency]; reasons.push(`urgency: ${lead.urgency}`); }
const intentText = `${lead.useCase} ${lead.notes}`.toLowerCase();
const keywords = ['automation', 'automate', 'crm', 'lead', 'integration', 'workflow', 'manual', 'n8n', 'ai'];
const matches = keywords.filter((keyword) => intentText.includes(keyword));
if (matches.length >= 3) { score += 20; reasons.push('strong automation intent'); }
else if (matches.length) { score += 10; reasons.push('automation intent'); }
const freeDomains = ['gmail.com', 'hotmail.com', 'icloud.com', 'outlook.com', 'proton.me', 'yahoo.com'];
if (!freeDomains.includes(email.split('@')[1])) { score += 10; reasons.push('business email'); }
if (lead.name && lead.company && lead.useCase) { score += 5; reasons.push('complete core profile'); }
score = Math.max(0, Math.min(100, score));
const route = score >= 70 ? 'hot' : score >= 40 ? 'warm' : 'cold';
const slaMinutes = { hot: 15, warm: 240, cold: 1440 };
const processedAt = new Date();
const followUpAt = new Date(processedAt.valueOf() + slaMinutes[route] * 60000);
let hash = 0x811c9dc5;
for (const char of `${lead.email}|${lead.company.toLowerCase()}`) {
  hash ^= char.charCodeAt(0);
  hash = Math.imul(hash, 0x01000193);
}
const idempotencyKey = (hash >>> 0).toString(16).padStart(8, '0');
const nextAction = {
  hot: 'Offer a priority discovery call.',
  warm: 'Send a relevant case study and ask one qualifying question.',
  cold: 'Add to educational nurture; no sales notification.',
}[route];
return [{ json: { idempotencyKey, processedAt: processedAt.toISOString(), followUpAt: followUpAt.toISOString(), lead, qualification: { score, route, reasons, nextAction } } }];
